// Test cases
function testIsValidBrackets() {
    // Test cases with expected results
    const testCases = [
        { input: "", expected: true, description: "empty string" },
        { input: "abc", expected: true, description: "string with only ordinary characters" },
        { input: "a(b)c[d]e{f}g", expected: true, description: "mixed with ordinary characters" },
        { input: "()", expected: true, description: "simple parentheses" },
        { input: "[]", expected: true, description: "simple square brackets" },
        { input: "{}", expected: true, description: "simple curly braces" },
        { input: "()[]{}", expected: true, description: "multiple bracket types" },
        { input: "( [ ] )", expected: true, description: "nested brackets with spaces" },
        { input: "([{}])", expected: true, description: "deeply nested brackets" },
        { input: "([)]", expected: false, description: "mismatched nesting" },
        { input: "(", expected: false, description: "unclosed opening bracket" },
        { input: ")", expected: false, description: "extra closing bracket" },
        { input: "({)}", expected: false, description: "mixed incorrect nesting" },
        { input: "((()))", expected: true, description: "multiple nested same type" },
        { input: "((())", expected: false, description: "unclosed nested brackets" },
        { input: null, expected: false, description: "null input" },
        { input: undefined, expected: false, description: "undefined input" },
        { input: 123, expected: false, description: "number input" },
        { input: {}, expected: false, description: "object input" },
        { input: [], expected: false, description: "array input" },
        { input: "a(b[c]d{e}f)g", expected: true, description: "complex mixed brackets" },
        { input: "a(b[c)d{e}f]g", expected: false, description: "complex mixed brackets with errors" }
    ];

    // Run tests
    let passed = 0;
    let failed = 0;

    for (const testCase of testCases) {
        const result = isValidBrackets(testCase.input);
        if (result === testCase.expected) {
            passed++;
            console.log(`✓ PASS: ${testCase.description}`);
        } else {
            failed++;
            console.log(`✗ FAIL: ${testCase.description} - Expected ${testCase.expected}, got ${result}`);
        }
    }

    console.log(`\nTest Results: ${passed} passed, ${failed} failed`);
}

// Run the tests
testIsValidBrackets();
```

**Explanation:**

The implementation uses a stack to track opening brackets as we encounter them. When we find a closing bracket, we check if it matches the most recent opening bracket (LIFO order). 

1. **Input Validation**: First, we check if the input is a string. If not, we return false.
2. **Stack Initialization**: We use an array as our stack and define a mapping of opening to closing brackets.
3. **Iteration**: For each character in the string:
   - If it's an opening bracket, push it to the stack
   - If it's a closing bracket:
     - Check if the stack is empty (no matching opening bracket)
     - Pop the last opening bracket and verify it matches
   - Non-bracket characters are ignored
4. **Final Check**: After processing all characters, if the stack isn't empty, some brackets weren't closed

The worst-case space is O(n) when all characters are opening brackets (e.g., "(((...(((...")) and we need to store them all in the stack until we find their closing matches.

The tests cover all specified cases including empty strings, ordinary characters, deeply nested brackets, extra closing brackets, unclosed opening brackets, and invalid input types.

I'll implement both iterative and recursive binary search functions that return the first occurrence of the target in a sorted array.

```js
/**
 * Performs binary search to find the first occurrence of target in a sorted array.
 * @param {Array<number|string>} sorted - The sorted array to search in
 * @param {number|string} target - The value to search for
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 * @throws {TypeError} If input is not an array
 * 
 * Time complexity: O(log n)
 * Space complexity: O(1)
 * 
 * Note: The input array must be sorted in ascending order. If the target is not
 * present in the array, the function returns -1.
 */
function binarySearch(sorted, target) {
    if (!Array.isArray(sorted)) {
        throw new TypeError('Input must be an array');
    }

    let left = 0;
    let right = sorted.length - 1;
    let result = -1;

    while (left <= right) {
        const mid = left + Math.floor((right - left) / 2);

        if (sorted[mid] === target) {
            result = mid;
            right = mid - 1; // Continue searching in the left half
        } else if (sorted[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return result;
}

/**
 * Performs recursive binary search to find the first occurrence of target in a sorted array.
 * @param {Array<number|string>} sorted - The sorted array to search in
 * @param {number|string} target - The value to search for
 * @param {number} [left=0] - The left boundary of the search range (internal use)
 * @param {number} [right] - The right boundary of the search range (internal use)
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 * @throws {TypeError} If input is not an array
 * 
 * Time complexity: O(log n)
 * Space complexity: O(log n) due to recursion stack
 * 
 * Note: The input array must be sorted in ascending order. If the target is not
 * present in the array, the function returns -1.
 */
function binarySearchRecursive(sorted, target, left = 0, right = sorted.length - 1) {
    if (!Array.isArray(sorted)) {
        throw new TypeError('Input must be an array');
    }

    if (left > right) {
        return -1;
    }

    const mid = left + Math.floor((right - left) / 2);

    if (sorted[mid] === target) {
        // Check if this is the first occurrence
        if (mid === 0 || sorted[mid - 1] < target) {
            return mid;
        }
        // Continue searching in the left half
        return binarySearchRecursive(sorted, target, left, mid - 1);
    } else if (sorted[mid] < target) {
        return binarySearchRecursive(sorted, target, mid + 1, right);
    } else {
        return binarySearchRecursive(sorted, target, left, mid - 1);
    }
}
```

### Explanation:

**Iterative Implementation:**
1. Uses a while loop to narrow down the search range
2. When the target is found, continues searching to the left to find the first occurrence
3. Maintains O(log n) time complexity and O(1) space complexity
4. Returns -1 if the target is not found

**Recursive Implementation:**
1. Uses recursion to divide the search range
2. When the target is found, checks if it's the first occurrence by comparing with the previous element
3. If not the first occurrence, continues searching to the left
4. Maintains O(log n) time complexity but uses O(log n) space due to recursion stack
5. Returns -1 if the target is not found
6. Includes validation for null/undefined input (throws TypeError)

**Key Points:**
- Both implementations use the safe midpoint computation: `left + Math.floor((right - left) / 2)`
- Neither implementation mutates or sorts the input array
- Both return the index of the first occurrence of the target
- Both handle cases where the target is not present by returning -1
- Both validate that the input is an array

**Example Usage:**
```js
const arr = [1, 2, 2, 3, 3, 3, 4, 5, 5];
console.log(binarySearch(arr, 3)); // Output: 3 (first occurrence of 3)
console.log(binarySearchRecursive(arr, 5)); // Output: 7 (first occurrence of 5)
console.log(binarySearch(arr, 6)); // Output: -1 (not found)
```

